&\tilde{g}_{i,n,\mathbb M}(y) = U_n^{-1}X_{i,n}[M]'\hat{u}_{i,\mathbb M}(y) \\
&\quad=
U_n^{-1}X_{i,n}[M]'\left( u_{i,n}(y_i)  + X_{i,n}(\beta_{\mathbb M,n}^* - \hat{\beta}_{\mathbb M,n}(y)) + \mu_{i,n}-X_{i,n}[M]\beta_{\mathbb M,n}^*\right)\\
&\quad= \hat{g}_{i,n,\mathbb M}(y) + a_{i,n,\mathbb M},
\end{align*}

If $r_n$ is now, again, the stacked vector of the $r_{n,\mathbb M_1},\dots, r_{n,\mathbb M_d}$, then, by Lemma~\ref{lem:upper}, we have that $B_{\alpha}(\min(k, p),k) \geq K_{1-\alpha}(\mathrm{corr}(\mathbb{V}_n(r_n))) > 0$ (it is easy to see that the rank of the $k \times k$-dimensional matrix $\mathbb{V}_n(r_n)$ can not exceed $p$), so we can apply the special case discussed in Theorem~\ref{thm:cons} to conclude that 

\begin{equation}
\liminf_{n \to \infty}  \mathbb{P}_n \left(\beta_{\hat{\mathbb{M}}_n, n}^{*, (j)} \in \mathrm{CI}_{1-\alpha, \hat{\mathbb{M}}_n}^{(j), \mathrm{hlm}} \text{ for all } j = 1, \hdots, m(\hat{\mathbb{M}}_n)  \right) \geq 1-\alpha,
\end{equation}

which proves the claim as the sequence $\mathbb{P}_n \in \mathbf{P}_n^{(\mathrm{het})}(\delta, \tau)$ was arbitrary.\hfill\qed

Fix $\mathbb M\in\mathsf{M}_n$ and ${\mathbb P}_n\in\bigcup_{\delta>0}\mathbf{P}_n^{(\mathrm{bin})}(\delta)$ and recall that $\mathbb M\triangleq (h,M)\in \mathcal H\times \mathcal I$. For $i=1,\dots, n$, we abbreviate $p_i = {\mathbb P}_{i,n}(\{1\})$ and for $\gamma\in{\mathbb R}$, $\phi_1(\gamma) = \log(h(\gamma))$, $\phi_2(\gamma) = \log(1-h(\gamma))$, and we note that $p_i\in(0,1)$. Thus, the expected log-likelihood function can be expressed as
\begin{equation}\label{eq:Eloglik}
\beta \mapsto \int_{{\mathbb R}^n}\ell_{\mathbb M,n}(y,\beta)\,d{\mathbb P}_n(y) = \sum_{i=1}^n \left[p_i\phi_1(X_{i,n}[M]\beta) + (1-p_i)\phi_2(X_{i,n}[M]\beta)\right].
\end{equation}
The function in the previous display is continuous on its domain ${\mathbb R}^{|M|}$, by Condition~\ref{cond:H}\eqref{cH:cdf}. To see that it also has a maximizer on ${\mathbb R}^{|M|}$, consider an arbitrary sequence $\beta_k\in{\mathbb R}^{|M|}$ such that $\|\beta_k\|\to\infty$ as $k\to\infty$. Then $\|X_n[M]\beta_k\|^2 \ge \|\beta_k\|^2 \lambda_{\min}(X_n[M]'X_n[M]) \to \infty$ as $k\to \infty$, by Condition~\ref{cond:X2}\eqref{cX2:rank}, so that at least for a sequence $i_k\in\{1,\dots, n\}$, we must have $|X_{i_k,n}[M]\beta_k|\to \infty$ as $k\to\infty$. Therefore, using the fact that $p_i\in(0,1)$ for $i=1,\dots, n$, it is easy to see that the sequence of summands in \eqref{eq:Eloglik} corresponding to the indices $i_k$, $k\in{\mathbb N}$, with $\beta$ replaced by $\beta_k$, converges to $-\infty$ as $k\to \infty$. Since for each $k$ the remaining summands in \eqref{eq:Eloglik} are non-positive, we see that the expected log-likelihood diverges to $-\infty$ along $(\beta_k)$, and thus, by continuity, attains its maximum at some $\beta_{\mathbb M,n}^*=\beta_{\mathbb M,n}^*({\mathbb P}_n,X_n[M])\in{\mathbb R}^{|M|}$.

\begin{align*}
{\mathbb E}_n[\ell_{\mathbb M,n}(\cdot,\beta)] \;&\le\; \sum_{i\in R_{\beta,n}(\xi)}  {\mathbb P}_{i,n}(\{1\}){\mathbb P}_{i,n}(\{0\})  \Big( \phi_1(X_{i,n}[M]\beta) + \phi_2(X_{i,n}[M]\beta)\Big)\\
&\le \; \tau \,|R_{\beta,n}(\xi)| \,g_h(\xi\|U_{M,n}^{1/2}\beta\|) \;\le\; n \frac{\tau}{2C} g_h(\|U_{M,n}^{1/2}\beta\|/\sqrt{2}),
\end{align*}

\begin{align*}
&\max_{i}|X_{i,n}[M]\beta_{\mathbb M,n}^*({\mathbb P}_n)| \le \max_i \|U_{M,n}^{-1/2}X_{i,n}[M]'\| \|U_{M,n}^{1/2}\beta_{\mathbb M,n}^*({\mathbb P}_n)\|\\
&\quad\le
\sqrt{C}K_{h,M}^*(\tau, C) \le \max_{(h,M)\in\mathcal H\times \mathcal I}\sqrt{C}K_{h,M}^*(\tau, C) =:K^*(\tau, C).
\end{align*}

\label{lemma:Hcontinuity}
Suppose that Conditions~\ref{cond:X2}(\ref{cX2:rank},\ref{cX2:Huber}) and \ref{cond:H}(\ref{cH:cdf},\ref{cH:concave},\ref{cH:C2}) hold and fix $\tau\in(0,1/4)$. 
