\item \label{l:Hcont:A}
There exist positive constants $\overline{K}(\tau, C)$ and $\underline{K}(\tau, C)$, depending only on $\tau$ and the constant $C$ from Condition~\ref{cond:X2}\eqref{cX2:Huber}, such that for all sufficiently large $n\in{\mathbb N}$, for all $\mathbb M\in\mathsf{M}_n$, all ${\mathbb P}_n\in\mathbf{P}_n^{(\mathrm{bin})}(\tau)$ and all $y\in\{0,1\}^n$, 
\begin{align*}
\overline{K}(\tau, C) &\ge
\lambda_{\max}\left((X_n[M]'X_n[M])^{-1/2}H_{\mathbb M,n}^*(y)(X_n[M]'X_n[M])^{-1/2}\right)\\
&\ge\lambda_{\min}\left((X_n[M]'X_n[M])^{-1/2}H_{\mathbb M,n}^*(y)(X_n[M]'X_n[M])^{-1/2}\right) \ge \underline{K}(\tau, C),
\end{align*}
where $H_{\mathbb M,n}^*(y) := H_{\mathbb M,n}(y,\beta_{\mathbb M,n}^*({\mathbb P}_n))$, $H_{\mathbb M,n}(y,\beta) = -\frac{\partial^2 \ell_{\mathbb M,n}(y,\beta)}{\partial\beta\partial\beta'}$ with $\beta\in{\mathbb R}^{m(\mathbb M)}$ and $\beta_{\mathbb M,n}^*({\mathbb P}_n)$ is the pseudo parameter of Lemma~\ref{lemma:pseudo}.


\item \label{l:Hcont:B}
For $\delta>0$ and $n$ sufficiently large, such that the pseudo parameter $\beta_{\mathbb M,n}^*$ of Lemma~\ref{lemma:pseudo} exists, define 
$$
N_{\mathbb M,{\mathbb P}_n,n}(\delta) = \left\{ \beta\in{\mathbb R}^{m(\mathbb M)} : \left\| (X_n[M]'X_n[M])^{1/2}(\beta - \beta_{\mathbb M,n}^*({\mathbb P}_n)) \right\| \le \delta\right\}.
$$
Then, for every $\delta>0$,
$$
\sup_{\substack{\mathbb M\in\mathsf{M}_n\\{\mathbb P}_n\in\mathbf{P}_n^{(\mathrm{bin})}(\tau)}}
\sup_{y\in\{0,1\}^n}\sup_{\beta\in N_{\mathbb M,{\mathbb P}_n,n}(\delta)} \left\| H_{\mathbb M,n}^*(y)^{-1/2}H_{\mathbb M,n}(y,\beta)H_{\mathbb M,n}^*(y)^{-1/2} - I_{m(\mathbb M)} \right\|
$$
converges to zero as $n\to\infty$.


\item \label{l:Hcont:C}
Suppose that, in addition, also Condition~\ref{cond:X2}\eqref{cX2:eigen} holds. Then there exists a positive finite constant $K(\tau, C)$, depending only on $\tau$ and the constant $C$ from Condition~\ref{cond:X2}, such that eventually
$$
\sup_{\mathbb M\in\mathsf{M}_n}\sup_{{\mathbb P}_n\in\mathbf{P}_n^{\mathrm{(bin)}}(\tau)}\frac{\lambda_{\max}({\mathbb E}_{{\mathbb P}_n}[H_{\mathbb M,n}^*])}{\lambda_{\min}({\mathbb E}_{{\mathbb P}_n}[H_{\mathbb M,n}^*])} \;\le\; K(\tau, C).
$$

